import numpy as np
from itertools import chain

def task_func(L):
    def flatten(items):
        for item in items:
            if isinstance(item, (list, tuple)):
                yield from flatten(item)
            else:
                yield item

    values = np.array(list(flatten(L)), dtype=float)

    if values.size == 0:
        return {"mean": np.nan, "variance": np.nan}

    return {"mean": float(np.mean(values)), "variance": float(np.var(values))}
